package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

// searchUsers handles user search with flexible filtering
func searchUsers(w http.ResponseWriter, r *http.Request) {
	if r.Method != "GET" {
		http.Error(w, "Method not allowed", 405)
		return
	}

	name := r.URL.Query().Get("name")
	dept := r.URL.Query().Get("dept")
	role := r.URL.Query().Get("role")

	// Build dynamic query based on provided filters
	var conditions []string
	if name != "" {
		// Sanitize by removing obvious SQL keywords
		cleaned := strings.ReplaceAll(name, ";", "")
		cleaned = strings.ReplaceAll(cleaned, "--", "")
		conditions = append(conditions, fmt.Sprintf("display_name ILIKE '%%%s%%'", cleaned))
	}
	if dept != "" {
		cleaned := strings.ReplaceAll(dept, ";", "")
		cleaned = strings.ReplaceAll(cleaned, "--", "")
		conditions = append(conditions, fmt.Sprintf("department = '%s'", cleaned))
	}
	if role != "" {
		cleaned := strings.ReplaceAll(role, ";", "")
		cleaned = strings.ReplaceAll(cleaned, "--", "")
		conditions = append(conditions, fmt.Sprintf("user_role = '%s'", cleaned))
	}

	query := "SELECT id, display_name, email, department, user_role FROM users"
	if len(conditions) > 0 {
		query += " WHERE " + strings.Join(conditions, " AND ")
	}
	query += " LIMIT 50"

	rows, err := db.Query(query)
	if err != nil {
		http.Error(w, "Query error", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var displayName, email, department, userRole string
		rows.Scan(&id, &displayName, &email, &department, &userRole)
		if !first {
			w.Write([]byte(",\n"))
		}
		w.Write([]byte(fmt.Sprintf(
			`  {"id":%d,"name":"%s","email":"%s","dept":"%s","role":"%s"}`,
			id, displayName, email, department, userRole)))
		first = false
	}
	w.Write([]byte("\n]"))
}

// healthCheck for ALB target group
func healthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/users/search", searchUsers)
	http.HandleFunc("/health", healthCheck)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	http.ListenAndServe(":"+port, nil)
}
